--- 构造奖励和任务数据
function UISweepResultDialog:MakeLoopViewListData()
    local data = {}
    -- 构造奖励数据
    local rewardsData = self:GetRewardsData()
    table.link(data, rewardsData)

    -- self.params.questGradeTaskProgress = {
    --     ["10906"] = {
    --         ["newProgress"] = 3,
	-- 		["taskId"] = 10906,
	-- 		["oldProgress"] = 2,
    --     },
    --     ["10907"] = {
    --         ["newProgress"] = 3,
	-- 		["taskId"] = 10907,
	-- 		["oldProgress"] = 2,
    --     },
    -- }
    if not IsNull(self.params.questGradeTaskProgress) and table.count(self.params.questGradeTaskProgress) > 0 then
        -- 构造任务标题
        table.insert(data, {type = LoopListCellType.TaskTitle})
        -- 构造任务数据
        for taskId, taskInfo in pairs(self.params.questGradeTaskProgress) do
            table.insert(data, {type = LoopListCellType.Task, taskId = checkInt(taskId), taskInfo = taskInfo})
        end
    end
    -- print("[扫荡] 列表数据", table.dump(data,nil,3))
    return data
end

--- 从奖励列表里移除固定奖励
---@param jsonData any
function UISweepResultDialog:GetRewardsData()
    local rewardsList = checkTable(self.params.rewards)     -- clone(self.params.rewards)   -- 下面会修改rewards
    local extraRewardsList = checkTable(self.params.extraRewards)

    local rewardsData = {}

    -- 遍历x次的扫荡结果
    for index, rewards in pairs(rewardsList) do
        local extraRewards = extraRewardsList[index]
        -- 对每一次的扫荡结果，把额外奖励从奖励中剔除
        local needRemove = {}
        for i, v in ipairs(rewards) do
            if checkInt(v.from) == Constants.RewardSourceType.Fixed then
                table.insert(needRemove, i)
            end
        end
        for i, index in ipairs(needRemove) do
            table.remove(rewards, index)
        end
        -- 把扫荡结果加入数据列表
        rewardsData[checkInt(index)] = {
            type = LoopListCellType.Reward,
            rewards = rewards,
            extraRewards = extraRewards,
            index = checkInt(index),
        }
    end
    
    return rewardsData
end

---刷新滚动列表
function UISweepResultDialog:RefreshLoopList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UISweepResultDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1
    local data = self.loopViewListData[luaIndex]
    local cell
    if data.type == LoopListCellType.Reward then
        -- 扫荡奖励节点
        cell = loopListView:NewListViewItem("SweepCellNode")
        local LB_cell = GetLuaBehaviour(cell.gameObject, SweepRewardsLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
        end
        local LT_cell = LB_cell.Env
        LT_cell:SetRewards(data.rewards)
        LT_cell:SetExRewards(data.extraRewards)
        LT_cell:SetIndex(data.index)
    elseif data.type == LoopListCellType.TaskTitle then
        -- 任务标题节点
        cell = loopListView:NewListViewItem("TaskTitleNode")
    elseif data.type == LoopListCellType.Task then
        -- 任务节点
        cell = loopListView:NewListViewItem("TaskCellNode")
        local LB_cell = GetLuaBehaviour(cell.gameObject, TaskLuaPath)
        if not cell.IsInitHandlerCalled then
            cell.IsInitHandlerCalled = true
            LB_cell:Init()
        end
        local LT_cell = LB_cell.Env
        -- print("[大乱斗] cell data", table.dump(data, nil, 5))
        LT_cell:ShowTaskNode(data.taskId, data.taskInfo, 3)
    end

    if not isNull(cell) then
        local cg = cell.gameObject:GetComponent(typeof(CanvasGroup))
        if not isNull(cg) then
            cg.alpha = 1
        end
    end

    return cell
end

--- 根据内容量计算布局
function UISweepResultDialog:RefreshLayout()
    local SCREEN_HEIGHT = 1080  -- 这里用的是canvas的分辨率的高度
    local rewardsCount = table.count(self.params.rewards)
    local taskCount = table.count(checkTable(self.params.questGradeTaskProgress))
    -- 计算需要的总高度
    local rewardsHeight = rewardsCount * 218
    local titleHeight = taskCount > 0 and 60 or 0
    local tasksHeight = taskCount > 0 and taskCount * 137 or 0
    local needHeight = rewardsHeight + titleHeight + tasksHeight + 10
    -- 计算拥有的总高度
    local totalHeight = SCREEN_HEIGHT - 200 - 165 -- 减去经验条的高度，减去完成按钮的高度，获得剩余的最大高度

    if needHeight <= totalHeight then
        -- 空间足够，可以居中显示
        totalHeight = SCREEN_HEIGHT - 165   -- 只减去完成按钮的高度
        local expPosY = totalHeight * 0.5 - 0.5 * (200 + needHeight)
        local listPosY = 0.5 * SCREEN_HEIGHT - (expPosY + 200 + 0.5 * needHeight)
        local listSizeDeltaY = needHeight - SCREEN_HEIGHT
        -- local listTop = expPosY + 200
        -- local listBottom = SCREEN_HEIGHT - listTop - needHeight
        self.RT_ExpRoot.anchoredPosition = Vector2.New(0, -expPosY)
        self.RT_ListRoot.anchoredPosition = Vector2.New(0, listPosY)
        self.RT_ListRoot.sizeDelta = Vector2.New(1226, listSizeDeltaY)
    else
        -- 空间不足，直接拉满(已经在UI里默认设置成拉满了)
    end

    -- 把列表滚动到一个合适的位置
    local index = rewardsCount - 2
    self.LoopListView:MovePanelToItemIndex(index, 30)
end

--- 完成按钮回调
function UISweepResultDialog:OnCompleteClick()
    cs_coroutine.start(function()
        local co = self:ShowPlayerLevelUp()
        if co then
            cs_coroutine.yield_return(co)
        end

        -- 显示歼灭战的打脸界面
        if self.params.needShowAnnihilationPopup then
            ResourceModule.LoadGameObjectAsync(Constants.BattleEndCompResPath.CommonAnnihilationWarPopup, function(go)
                if not KTool.IsNull(go) then
                    go.name = "CommonAnnihilationWarPopup"
                    if not KTool.IsNull(go) then
                        local scr = CfUtils.GetLuaScr(go, Constants.BattleEndCompLuaPath.CommonAnnihilationWarPopup)
                        if scr then
                            local bossId = 1
                            bossId = checkInt(self.params.regionalBossData.bossTypeId)
                            scr:FillMatchSucInfo(bossId, function()
                                cs_coroutine.start(function()
                                    KTool.SafeDelete(go)

                                    -- goto boss panel
                                    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.params.questId)
                                    cs_coroutine.yield_return(UIModule.BackDialog())
                                    -- print("[扫荡] questVo", table.dump(questVo))
                                    CS.Engine.Lib.KCookie.Set("UIActionSecondMapDialogtargetPointId", questVo.pointID)
                                    local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                                    local vo = ActionUtils.GetRegionSecondaryMapVo(questVo.pointID)
                                    local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UISweepPrepareDialog)
                                    cs_coroutine.yield_return(UIModule.CloseDialog(dialog))
                                    
                                    CS.Engine.Lib.KCookie.Set("UIActionSecondMapDialogtargetPointId", questVo.pointID)
                                    UIModule.BackDialog()
                                    --UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionSecondMapDialog, parameters = {id = vo.regionBelong}}, {
                                    --    {id = Constants.UITypeIds.UIActionBossCollectionDialog }
                                    --})
                                end)
                            end)
                        end
                    end
                end
            end, true, UIModule.RootCanvas.transform)
        else
            UIModule.BackDialog()
        end
    end)
end

--- 显示玩家升级的打脸界面
function UISweepResultDialog:ShowPlayerLevelUp()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    if playerComponent then
        return playerComponent:ShowRewardsSpecialDialog()
    end
    return nil
end

return UISweepResultDialog
